const timeTrialStages = new Set([1, 16])

const buildOpeningSegments = (raw: RawStage): RawSegment[] => {
  const originalSegments = raw.segments
  const first = originalSegments[0]

  if (!first) return originalSegments

  if (timeTrialStages.has(raw.number)) {
    const warmup: RawSegment = {
      ...first,
      name: raw.number === 1 ? 'Barcelona Start-Ramp Warm-up' : 'Time Trial Start-Ramp Warm-up',
      type: 'Time trial warm-up',
      zone: 'Z1–Z2',
      power: 'Easy to 70% FTP',
      cadence: '88–98 rpm',
      resistance: '28–42%',
      routeKm: 0,
      sec: 360,
      desc: 'Progressive warm-up before the start ramp. Open the legs without creating fatigue.',
      fixed: [
        { at: 5, text: `Stage ${raw.number}. Begin the time trial warm-up. Smooth pressure, no wasted energy.` },
        { at: 120, text: 'Two minutes complete. Bring the cadence up and keep the upper body quiet.' },
        { at: 240, text: 'Two minutes to the start ramp. Add a little pressure, then settle.' },
        { at: 330, text: 'Thirty seconds until the start-ramp countdown.' },
      ],
      random: ['Easy speed. Save the race effort for the clock.', 'Breathe low and keep the pedal stroke round.'],
    }

    const countdown: RawSegment = {
      name: 'Start Ramp Countdown',
      type: 'Official time trial start',
      zone: 'Ready',
      power: 'Hold steady',
      cadence: '90–95 rpm',
      resistance: '35–45%',
      routeKm: 0,
      sec: 30,
      desc: 'Hold position on the start ramp as the official counts you into the race.',
      fixed: [
        { at: 1, text: 'Thirty seconds. Select your opening gear.' },
        { at: 20, text: 'Ten seconds.' },
        { at: 25, text: 'Five. Four. Three. Two. One.' },
        { at: 29, text: 'Go! The clock is running.' },
      ],
      random: [],
    }

    return [warmup, countdown, ...originalSegments.slice(1)]
  }

  const neutralStart: RawSegment = {
    ...first,
    name: `${raw.route.split('→')[0].trim()} Neutral Start`,
    type: raw.number === 21 ? 'Ceremonial neutral start' : 'Neutralized start',
    zone: 'Z1–Z2',
    power: 'Easy • under 65% FTP',
    cadence: '88–98 rpm',
    resistance: '25–38%',
    routeKm: 0,
    sec: raw.number === 21 ? 420 : 300,
    desc: raw.number === 21
      ? 'A relaxed ceremonial procession before the Paris circuits come alive.'
      : 'Ride behind the race director’s car. Warm the legs, review the plan, and hold position. Racing has not started.',
    fixed: [
      { at: 4, text: `Team, we have all eight riders still in the race. Today is Stage ${raw.number}, ${raw.route}. Lukas, Victor, and Jean, stay with Hal when the road climbs. Everyone else, protect position and cover the early moves.` },
      { at: 75, text: 'Use this rollout to warm the legs. Keep the effort easy and the cadence smooth.' },
      { at: 165, text: raw.note.length > 150 ? raw.note.slice(0, 147) + '...' : raw.note },
      { at: raw.number === 21 ? 330 : 240, text: 'Kilometre zero is approaching. Check your position and prepare for the flag.' },
      { at: raw.number === 21 ? 390 : 270, text: 'Thirty seconds to kilometre zero.' },
    ],
    random: ['Neutralized. No attacks yet.', 'Easy shoulders. Quiet breathing.', 'Hold the wheel and let the body wake up.'],
  }

  const kilometreZero: RawSegment = {
    name: 'Kilometre Zero',
    type: 'Race start',
    zone: 'Z2–Z3',
    power: 'Build to race pace',
    cadence: '90–100 rpm',
    resistance: '34–46%',
    routeKm: 0,
    sec: 45,
    desc: 'The race director drops the flag. Build smoothly into the opening race phase.',
    fixed: [
      { at: 1, text: 'Flag down. Racing begins now.' },
      { at: 15, text: 'The first attacks are moving. Build to race pace, do not sprint blindly.' },
      { at: 35, text: 'Ten seconds. Settle into the opening tactical block.' },
    ],
    random: [],
  }

  return [neutralStart, kilometreZero, ...originalSegments.slice(1)]
}


const targetMinutesByStage: Record<number, number> = {
  1: 45, 2: 60, 3: 75, 4: 65, 5: 50, 6: 90, 7: 50,
  8: 60, 9: 70, 10: 75, 11: 50, 12: 55, 13: 60, 14: 70,
  15: 65, 16: 45, 17: 80, 18: 85, 19: 80, 20: 90, 21: 60,
}

const expansionWeight = (segment: RawSegment): number => {
  const type = segment.type.toLowerCase()
  if (type.includes('cool')) return 0
  if (type.includes('race start') || type.includes('official time trial start')) return 0
  if (type.includes('sprint') || type.includes('attack') || type.includes('finale')) return 0.25
  if (type.includes('recovery') || type.includes('descent')) return 0.65
  if (type.includes('climb') || type.includes('mountain') || type.includes('summit')) return 1.25
  if (type.includes('tempo') || type.includes('endurance') || type.includes('rolling')) return 1.5
  return 1
}

const expandStageToTarget = (stageNumber: number, segments: RawSegment[]) => {
  const targetSeconds = (targetMinutesByStage[stageNumber] ?? 60) * 60
  const currentSeconds = segments.reduce((sum, segment) => sum + segment.sec, 0)
  const extraSeconds = Math.max(0, targetSeconds - currentSeconds)
  if (extraSeconds === 0) return segments

  const weights = segments.map(expansionWeight)
  const totalWeight = weights.reduce((sum, weight) => sum + weight, 0)
  let assigned = 0

  return segments.map((segment, index) => {
    if (weights[index] === 0 || totalWeight === 0) return segment
    const isLastWeighted = weights.slice(index + 1).every((weight) => weight === 0)
    const addition = isLastWeighted
      ? extraSeconds - assigned
      : Math.round((extraSeconds * weights[index]) / totalWeight / 15) * 15
    assigned += addition
    return { ...segment, sec: segment.sec + Math.max(0, addition) }
  })
}

const iconFor = (type: string) => {
  const value = type.toLowerCase()
  if (value.includes('cool')) return '🌅'
  if (value.includes('sprint') || value.includes('attack') || value.includes('surge')) return '🔥'
  if (value.includes('climb') || value.includes('summit')) return '⛰️'
  if (value.includes('descent') || value.includes('recovery')) return '↘️'
  if (value.includes('crosswind')) return '🌬️'
  if (value.includes('lead-out')) return '🚂'
  return '🚴'
}

export const raceStages: RaceStage[] = rawStages.map((raw) => ({
  number: raw.number, route: raw.route, title: raw.title, distanceKm: raw.distance, elevationM: raw.elevation,
  theme: raw.subtitle.split('•')[2]?.trim() ?? 'Race stage',
  difficulty: raw.number === 10 ? '9/10' : raw.number === 6 ? '9/10' : raw.number === 3 ? '8.5/10' : raw.number === 12 ? '7.5/10' : '7/10',
  objective: objectiveByStage[raw.number] ?? raw.note, teamOrders: ordersByStage[raw.number] ?? ['Follow Jean’s pacing plan.', 'Stay composed in the decisive block.', 'Finish the stage with purpose.'],
  profilePoints: profileByStage[raw.number] ?? ['0,78','12,72','24,62','36,74','48,48','60,68','72,38','84,58','94,26','100,64'],
  segments: expandStageToTarget(raw.number, buildOpeningSegments(raw)).map((segment) => ({
    ...segment, icon: iconFor(segment.type), description: segment.desc, terrainLabel: segment.type,
    objective: segment.type, secondaryObjective: 'Follow Jean’s pacing instructions',
  })),
})).sort((a, b) => a.number - b.number)

export function getRaceStage(stageNumber: number) {
  return raceStages.find((stage) => stage.number === stageNumber) ?? raceStages[0]
}
